WITH with_dims AS (SELECT e.*, c.name FROM sessions e LEFT JOIN customers c ON e.customer_id = c.id) SELECT customer_id, DATE_TRUNC('QUARTER', started_at) AS quarter_start, COUNT(*) AS cnt, SIZE(COLLECT_SET(country)) AS num_countries, SIZE(COLLECT_SET(device)) AS num_devices, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY SIZE(COLLECT_SET(country)) DESC) AS num_countries_percent_rank FROM with_dims GROUP BY customer_id, DATE_TRUNC('QUARTER', started_at) ORDER BY cnt DESC
